SELECT id,agreement_code,name AS agreement_name,valid_from,valid_to,status,created_at,updated_at,row_version FROM public.health_examination_agreements WHERE ORDER BY
agreement_code DESC, id ASC agreement_code ASC, id ASC name DESC, id ASC name ASC, id ASC valid_from DESC NULLS LAST, id ASC valid_from ASC NULLS LAST, id ASC status DESC, id ASC status ASC, id ASC created_at DESC, id ASC created_at ASC, id ASC id DESC id ASC
LIMIT #{limit} OFFSET #{offset}
